"use strict";
// Load-time timer housekeeping that leaves nothing behind: a clear of
// nothing, and a timer set and cleared again (smol-toml-like).
clearTimeout(undefined);
const probe = setTimeout(() => {
  throw new Error("never runs");
}, 1000);
clearTimeout(probe);

let calls = 0;
function twice(n) {
  calls += 1;
  return n * 2;
}
function count() {
  return calls;
}
module.exports = { twice, count };
